INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q952','nism-10a-z0','A monthly SIP of ₹3,000 earns 12% p.a. (monthly compounding, instalments at month-end) for 8 years. The maturity value is approximately:','["₹3,22,560","₹4,79,782","₹2,88,000","₹4,07,815"]',1,'FV = P × [((1 + r)^m − 1) ÷ r], r = i ÷ 12.',952) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q953','nism-10a-z0','A client earns ₹2,20,000 a month and saves ₹40,000. The savings ratio is:','["36.4%","81.8%","5.5%","18.2%"]',3,'Savings ratio = savings ÷ income.',953) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
