INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z0-q955','nism-10a-z0','Monthly expenses are ₹40,000 today. With inflation of 4% p.a., the monthly expense after 25 years will be approximately:','["₹80,000","₹98,589","₹10,00,000","₹1,06,633"]',3,'Future expense = today''s expense × (1 + inflation)^n.',955) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
